import java.io.*;
import java.net.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.regex.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class DiagnosticServlet extends HttpServlet {

    private static final Pattern SAFE_HOSTNAME_PATTERN = Pattern.compile("^[a-zA-Z0-9][a-zA-Z0-9._-]{0,253}[a-zA-Z0-9]$");
    private static final AtomicBoolean shuttingDown = new AtomicBoolean(false);
    private static final int MAX_CACHE_ENTRIES = 10000;
    private final ExecutorService diagnosticPool = Executors.newFixedThreadPool(4);
    private final ConcurrentHashMap<String, String> resolverCache = new ConcurrentHashMap<>();

    @Override
    public void init(ServletConfig config) throws ServletException {
        super.init(config);
        Runtime.getRuntime().addShutdownHook(new Thread(this::gracefulShutdown));
    }

    private void gracefulShutdown() {
        shuttingDown.set(true);
        diagnosticPool.shutdown();
        try {
            if (!diagnosticPool.awaitTermination(30, TimeUnit.SECONDS)) {
                diagnosticPool.shutdownNow();
            }
        } catch (InterruptedException e) {
            diagnosticPool.shutdownNow();
            Thread.currentThread().interrupt();
        }
        flushCacheToDisk();
    }

    private void flushCacheToDisk() {
        try (PrintWriter pw = new PrintWriter(new FileWriter("/var/log/app/resolver_cache.log"))) {
            resolverCache.forEach((k, v) -> pw.println(k + "=" + v));
        } catch (IOException e) {
            // best effort during shutdown
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        if (shuttingDown.get()) {
            resp.sendError(503, "Service shutting down");
            return;
        }

        String action = req.getParameter("action");
        if ("resolve".equals(action)) {
            handleResolve(req, resp);
        } else if ("health".equals(action)) {
            handleHealth(req, resp);
        } else {
            resp.sendError(400, "Unknown action");
        }
    }

    private void handleHealth(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        resp.setContentType("application/json");
        resp.getWriter().write("{\"status\":\"ok\",\"shutting_down\":" + shuttingDown.get() + "}");
    }

    private void handleResolve(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String target = req.getParameter("target");
        if (target == null || target.isEmpty()) {
            resp.sendError(400, "Missing target parameter");
            return;
        }

        String sanitized = sanitizeHostname(target);
        if (sanitized == null) {
            resp.sendError(400, "Invalid hostname format");
            return;
        }

        String cached = resolverCache.get(sanitized);
        if (cached != null) {
            resp.setContentType("text/plain");
            resp.getWriter().write(cached);
            return;
        }

        try {
            Future<String> future = diagnosticPool.submit(() -> performResolution(sanitized));
            String result = future.get(10, TimeUnit.SECONDS);
            // Bound cache size to prevent unbounded memory growth (DoS).
            if (resolverCache.size() < MAX_CACHE_ENTRIES) {
                resolverCache.put(sanitized, result);
            }
            resp.setContentType("text/plain");
            resp.getWriter().write(result);
        } catch (TimeoutException e) {
            resp.sendError(504, "Resolution timed out");
        } catch (Exception e) {
            resp.sendError(500, "Resolution failed");
        }
    }

    private String sanitizeHostname(String input) {
        if (input == null) return null;
        String trimmed = input.trim();
        if (trimmed.length() < 2 || trimmed.length() > 255) return null;
        if (!SAFE_HOSTNAME_PATTERN.matcher(trimmed).matches()) return null;
        // Additional check: no consecutive dots
        if (trimmed.contains("..")) return null;
        return trimmed;
    }

    private String performResolution(String hostname) throws IOException {
        // Use system resolver for enhanced diagnostics including TTL info
        // Java's InetAddress doesn't expose TTL, so we use nslookup
        String[] command = buildResolverCommand(hostname);
        Process proc = Runtime.getRuntime().exec(command);
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(proc.getInputStream()))) {
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line).append("\n");
            }
            proc.waitFor(5, TimeUnit.SECONDS);
            return sb.toString();
        } catch (InterruptedException e) {
            proc.destroyForcibly();
            Thread.currentThread().interrupt();
            throw new IOException("Interrupted during resolution");
        }
    }

    private String[] buildResolverCommand(String hostname) {
        // hostname has been validated against SAFE_HOSTNAME_PATTERN
        // which only allows alphanumeric, dots, hyphens, underscores
        return new String[]{"nslookup", hostname};
    }
}
